import { create } from 'zustand';
import { KDSOrder, KitchenStage } from '../types/kds';

interface QueuedAction {
    id: string;
    type: 'UPDATE_STAGE' | 'DELAY_ORDER';
    payload: any;
    timestamp: number;
}

interface KDSState {
    orders: Record<string, KDSOrder>;
    isOnline: boolean;
    offlineQueue: QueuedAction[];

    addOrUpdateOrder: (order: KDSOrder) => void;
    removeOrder: (orderId: string) => void;
    updateOrderStage: (orderId: string, stage: KitchenStage) => void;
    advanceStage: (orderId: string) => void;
    markDelayed: (orderId: string, reason?: string) => void;
    delayOrder: (orderId: string, additionalMinutes: number, reason?: string) => void;
    setOnline: (status: boolean) => void;
    processQueue: () => void;
}

export const useKDSStore = create<KDSState>((set, get) => ({
    orders: {},
    isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
    offlineQueue: [],

    addOrUpdateOrder: (order) =>
        set((state) => ({
            orders: {
                ...state.orders,
                [order.id]: order, // idempotent replacement
            },
        })),

    removeOrder: (orderId) =>
        set((state) => {
            const newOrders = { ...state.orders };
            delete newOrders[orderId];
            return { orders: newOrders };
        }),

    updateOrderStage: (orderId, stage) => {
        const { isOnline } = get();

        // Immediate local update
        set((state: KDSState) => {
            const order = state.orders[orderId];
            if (!order) return state;

            const now = new Date();
            let updates: Partial<KDSOrder> = {
                stage,
                stageStartedAt: now.toISOString(),
            };

            // Workflow automation: If starting PREPARATION, ensure prepTime and ETA are set
            if (stage === 'PREPARATION') {
                const prepTime = order.prepTimeMinutes || 10;
                const createdAt = new Date(order.createdAt);
                createdAt.setMinutes(createdAt.getMinutes() + prepTime);

                updates = {
                    ...updates,
                    prepTimeMinutes: prepTime,
                    estimatedReadyTime: createdAt.toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: false
                    })
                };
            }

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        ...updates,
                    },
                },
            };
        });

        // Queue if offline
        if (!isOnline) {
            set((state: KDSState) => ({
                offlineQueue: [
                    ...state.offlineQueue,
                    {
                        id: crypto.randomUUID(),
                        type: 'UPDATE_STAGE',
                        payload: { orderId, stage },
                        timestamp: Date.now()
                    }
                ]
            }));
        }
    },

    advanceStage: (orderId: string) => {
        const currentOrder = get().orders[orderId];
        if (!currentOrder) return;

        // If already READY, "advancing" means completing/removing the order
        if (currentOrder.stage === 'READY') {
            get().removeOrder(orderId);
            return;
        }

        set((state: KDSState) => {
            const order = state.orders[orderId];
            if (!order) return state;

            const stages: KitchenStage[] = ['ACCEPTED', 'PREPARATION', 'CUTTING', 'READY'];
            const currentIndex = stages.indexOf(order.stage);
            const nextStage = stages[currentIndex + 1];

            if (!nextStage) return state;

            const now = new Date().toISOString();
            const prevStageEntry = {
                stage: order.stage,
                startedAt: order.stageStartedAt || order.createdAt,
                completedAt: now,
            };

            const stageHistory = [...(order.stageHistory || []), prevStageEntry];

            let updates: Partial<KDSOrder> = {
                stage: nextStage,
                stageStartedAt: now,
                stageHistory,
            };

            // Workflow automation: If starting PREPARATION, ensure prepTime and ETA are set
            if (nextStage === 'PREPARATION') {
                const prepTime = order.prepTimeMinutes || 10;
                const createdAt = new Date(order.createdAt);
                createdAt.setMinutes(createdAt.getMinutes() + prepTime);

                updates = {
                    ...updates,
                    prepTimeMinutes: prepTime,
                    estimatedReadyTime: createdAt.toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: false
                    })
                };
            }

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        ...updates,
                    },
                },
            };
        });
    },

    markDelayed: (orderId, reason) =>
        set((state) => {
            const order = state.orders[orderId];
            if (!order) return state;

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        isDelayed: true,
                        delayReason: reason,
                    },
                },
            };
        }),

    delayOrder: (orderId: string, additionalMinutes: number, reason?: string) => {
        const { isOnline } = get();

        // Immediate local update
        set((state) => {
            const order = state.orders[orderId];
            if (!order) return state;

            // Safe ETA update logic
            let newETA = order.estimatedReadyTime;
            try {
                const parts = order.estimatedReadyTime.split(':').map(Number);
                const hrs = parts[0];
                const mins = parts[1];
                if (hrs !== undefined && mins !== undefined && !isNaN(hrs) && !isNaN(mins)) {
                    const date = new Date();
                    date.setHours(hrs);
                    date.setMinutes(mins + additionalMinutes);

                    newETA = date.toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                        hour12: false
                    });
                }
            } catch (e) {
                console.error('Failed to update ETA:', e);
            }

            return {
                orders: {
                    ...state.orders,
                    [orderId]: {
                        ...order,
                        prepTimeMinutes: (order.prepTimeMinutes || 0) + additionalMinutes,
                        estimatedReadyTime: newETA,
                        isDelayed: true,
                        delayReason: reason || order.delayReason,
                    },
                },
            };
        });

        // Queue if offline
        if (!isOnline) {
            set((state) => ({
                offlineQueue: [
                    ...state.offlineQueue,
                    {
                        id: crypto.randomUUID(),
                        type: 'DELAY_ORDER',
                        payload: { orderId, additionalMinutes, reason },
                        timestamp: Date.now()
                    }
                ]
            }));
        }
    },

    setOnline: (status) => {
        const wasOffline = !get().isOnline;
        set({ isOnline: status });

        if (status && wasOffline) {
            get().processQueue();
        }
    },

    processQueue: () => {
        const { offlineQueue } = get();
        if (offlineQueue.length === 0) return;

        console.log(`📡 Reconnecting: Replaying ${offlineQueue.length} queued actions...`);

        // In a real app, we would send these to the API.
        // For this task, we just log and clear to avoid duplicate replays.
        set({ offlineQueue: [] });
    },
}));
