'use client';

import { useState } from 'react';
import { KDSOrder } from '../../types/kds';
import { SourceBadge } from './SourceBadge';
import { DelayOrderModal } from '../modals/DelayOrderModal';
import { useKDSStore } from '../../store/kdsStore';
import { TicketTimer } from './TicketTimer';

interface Props {
    order: KDSOrder;
    variant?: 'standard' | 'expo';
}

export function OrderTicket({ order, variant = 'standard' }: Props) {
    const [isDelayModalOpen, setIsDelayModalOpen] = useState(false);
    const [isProcessing, setIsProcessing] = useState(false);
    const { delayOrder, advanceStage } = useKDSStore();

    // Production visual states logic
    const getBorderState = () => {
        if (order.isDelayed) return 'border-red-600 border-[4px]';
        if (order.stage === 'READY') return 'border-green-500 border-[4px]';
        if (order.stage === 'CUTTING') return 'border-purple-500 border-[4px]';
        if (order.stage === 'PREPARATION') return 'border-[#1FA4A9] border-[4px]';
        return 'border-slate-200 border-[1px]';
    };

    const handleAdvance = async () => {
        if (isProcessing) return;
        setIsProcessing(true);

        // Sound confirmation
        try {
            const audio = new Audio('/sounds/confirm.mp3');
            audio.play().catch(() => { });
        } catch (e) { }

        // Mock delay for visual transition - allow time for slide-out animation if any
        setTimeout(() => {
            advanceStage(order.id);
            setIsProcessing(false);
        }, 300);
    };

    const handleDelayConfirm = (minutes: number, reason: string) => {
        delayOrder(order.id, minutes, reason);

        // Trigger delay sound (placeholder)
        try {
            const audio = new Audio('/sounds/alert.mp3');
            audio.play().catch(() => { });
        } catch (e) { }
    };

    const formatCreatedAt = (dateStr: string) => {
        try {
            const date = new Date(dateStr);
            return date.toLocaleTimeString('en-US', {
                hour: '2-digit',
                minute: '2-digit',
                hour12: false
            });
        } catch {
            return '--:--';
        }
    };

    const getActionButton = () => {
        if (variant === 'expo') {
            return (
                <div className="flex gap-2">
                    <button
                        onClick={() => {
                            // Placeholder for print label
                            alert(`Printing label for #${order.orderNumber}`);
                        }}
                        className="flex-1 bg-slate-200 text-slate-800 h-[60px] rounded-xl font-black uppercase tracking-widest text-xs hover:bg-slate-300 transition-all border-2 border-slate-300"
                    >
                        Print Label
                    </button>
                    <button
                        disabled={isProcessing}
                        onClick={handleAdvance}
                        className="flex-[2] bg-slate-900 text-white h-[60px] rounded-xl font-black uppercase tracking-widest text-sm hover:bg-slate-800 active:scale-[0.98] transition-all disabled:opacity-50 shadow-lg"
                    >
                        {isProcessing ? 'Saving...' : 'Mark Completed'}
                    </button>
                </div>
            );
        }

        // Stage flow: ACCEPTED -> PREPARATION -> CUTTING -> READY
        if (order.stage === 'READY') {
            return (
                <button
                    disabled={isProcessing}
                    onClick={handleAdvance}
                    className="w-full bg-slate-900 text-white h-[60px] rounded-xl font-black uppercase tracking-widest text-sm hover:bg-slate-800 active:scale-[0.98] transition-all disabled:opacity-50 shadow-lg"
                >
                    {isProcessing ? 'Processing...' : 'Mark Completed'}
                </button>
            );
        }

        return (
            <button
                disabled={isProcessing}
                onClick={handleAdvance}
                className={`w-full h-[60px] rounded-xl font-black uppercase tracking-widest text-sm active:scale-[0.98] transition-all disabled:opacity-50 ${order.stage === 'ACCEPTED' ? 'bg-[#1FA4A9] text-white' :
                    order.stage === 'PREPARATION' ? 'bg-slate-950 text-white' :
                        'bg-purple-600 text-white'
                    }`}
            >
                {isProcessing ? 'Processing...' : 'Next Stage'}
            </button>
        );
    };

    const getFulfillmentStyle = () => {
        if (variant !== 'expo') return 'bg-slate-100 text-slate-700';

        const type = order.fulfillment_type;
        if (type.includes('DELIVERY')) {
            return 'bg-amber-100 text-amber-700 border border-amber-200';
        }
        return 'bg-blue-100 text-blue-700 border border-blue-200';
    };

    return (
        <>
            <div
                className={`kds-ticket bg-white rounded-xl shadow-xl flex flex-col overflow-hidden transition-all duration-500 kds-animate-in ${getBorderState()} ${isProcessing ? 'opacity-50 translate-x-4 grayscale-[0.2]' : ''} ${variant === 'expo' ? 'min-h-[450px] w-full max-w-[600px] mx-auto' : 'min-h-[280px]'}`}
            >
                {/* TOP ROW */}
                <div className={`p-4 border-bottom border-slate-100 flex justify-between items-start ${variant === 'expo' ? 'bg-slate-900 text-white' : 'bg-slate-50'}`}>
                    <div className="flex flex-col gap-1">
                        <h2 className={`font-black tracking-tighter ${variant === 'expo' ? 'text-[42px]' : 'text-[28px] leading-tight text-slate-950'}`}>
                            #{order.orderNumber}
                        </h2>
                        <div className="flex items-center gap-2">
                            <SourceBadge source={order.order_source} />
                            {variant !== 'expo' && (
                                <button
                                    onClick={() => setIsDelayModalOpen(true)}
                                    className="text-[10px] font-black uppercase text-red-500 hover:bg-red-50 px-2 py-1 rounded transition-all"
                                >
                                    + Delay
                                </button>
                            )}
                        </div>
                    </div>
                    <div className="text-right">
                        <span className={`text-xs font-bold uppercase tracking-tighter ${variant === 'expo' ? 'text-slate-400' : 'text-slate-400'}`}>
                            CREATED: {formatCreatedAt(order.createdAt)}
                        </span>
                    </div>
                </div>

                {/* SECOND ROW */}
                <div className={`px-4 py-2 flex justify-between items-center border-y border-slate-200 ${getFulfillmentStyle()}`}>
                    <span className="text-sm font-black uppercase tracking-widest">
                        {order.fulfillment_type.replace(/_/g, ' ')}
                    </span>
                    <span className={`px-2 py-0.5 text-white text-[10px] font-black rounded uppercase tracking-widest ${variant === 'expo' ? 'bg-green-600' : 'bg-slate-800'}`}>
                        {order.stage}
                    </span>
                </div>

                {/* MIDDLE SECTION - ITEM LIST */}
                <div className="p-4 flex-1 overflow-y-auto max-h-[400px]">
                    {order.isDelayed && order.delayReason && (
                        <div className="mb-4 p-3 bg-red-50 border border-red-100 rounded-lg">
                            <span className="text-[10px] font-black text-red-400 uppercase tracking-widest block mb-1">Reason for Delay</span>
                            <p className="text-xs font-bold text-red-700 italic">"{order.delayReason}"</p>
                        </div>
                    )}

                    <div className="space-y-4">
                        {order.items.map((item, idx) => (
                            <div key={idx} className="border-b border-slate-50 last:border-0 pb-3 last:pb-0">
                                <div className="flex items-start gap-2">
                                    <span className="text-[20px] font-black text-slate-900 leading-none mt-1">
                                        1x
                                    </span>
                                    <div className="flex flex-col">
                                        <span className="text-[20px] font-bold text-slate-900 leading-tight">
                                            {item.name}
                                        </span>
                                        {item.variant && (
                                            <span className="text-sm font-semibold text-slate-500 italic">
                                                {item.variant}
                                            </span>
                                        )}
                                    </div>
                                </div>

                                {/* Modifiers */}
                                {item.modifiers.length > 0 && (
                                    <div className="ml-8 mt-2 space-y-1">
                                        {item.modifiers.map((mod, modId) => (
                                            <div key={modId} className="flex items-center gap-2 text-md font-bold text-slate-600">
                                                <span className="text-blue-500">+</span>
                                                <span>{mod.name}</span>
                                                <span className="text-[10px] px-1.5 py-0.5 bg-slate-200 text-slate-500 rounded uppercase">
                                                    {mod.placement || 'FULL'}
                                                </span>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>

                {/* BOTTOM SECTION */}
                <div className="p-4 mt-auto border-t border-slate-200 bg-slate-50 flex flex-col gap-3">
                    <div className="flex justify-between items-center">
                        <div className="flex flex-col">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">EST. READY</span>
                            <span className="text-xl font-black text-slate-800 tracking-tight">
                                {order.estimatedReadyTime}
                            </span>
                        </div>
                        <TicketTimer order={order} />
                    </div>

                    {getActionButton()}
                </div>
            </div>

            <DelayOrderModal
                isOpen={isDelayModalOpen}
                onClose={() => setIsDelayModalOpen(false)}
                onConfirm={handleDelayConfirm}
                orderNumber={order.orderNumber}
            />
        </>
    );
}
